import type { NodeConfig } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { TOC_TYPE } from '../types.js';
import { Toc as Component } from './component.js';

export const tiptapExtensions = [
  createRicosNodeExtension({
    groups: ['draggable', 'not-overtypable'],
    type: 'react-node',
    Component,
    reconfigure: (config: NodeConfig, _extensions, _props, settings: Record<string, unknown>) => ({
      ...config,
      addOptions: () => settings,
    }),
    name: TOC_TYPE,
    createExtensionConfig() {
      return {
        name: this.name,
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        addAttributes: () => ({
          includedHeadings: null,
          listStyle: null,
          fontSize: null,
          itemSpacing: null,
          color: null,
          indentation: null,
        }),
      };
    },
  }),
];
