import React from 'react';

import type { TocData } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { debounce } from './../../_shared/debounce.js';
import type { PmTocNode } from './../../_shared/pm-node-types.js';
import { NodeSelection } from './../../tiptap/pm/state.js';

import { extractHeadingsFromPmDoc } from '../heading-extraction.js';
import { getScrollBehavior, TocView } from '../toc-view.js';

export const Toc: React.FC<PluginProps> = ({ editor, node, getPos, selected }) => {
  const data = node.attrs as PmTocNode['attrs'];
  const includedLevelsKey = React.useMemo(
    () => (data.includedHeadings || []).join(','),
    [data.includedHeadings]
  );
  const [headings, setHeadings] = React.useState<ReturnType<typeof extractHeadingsFromPmDoc>>([]);

  React.useEffect(() => {
    const sync = () => {
      setHeadings(extractHeadingsFromPmDoc(editor.state.doc, data.includedHeadings));
    };

    const debouncedSync = debounce(sync, 60, { leading: true });

    sync();
    editor.on('update', debouncedSync);

    return () => {
      editor.off('update', debouncedSync);
      debouncedSync.cancel();
    };
  }, [editor, includedLevelsKey]);

  const wasSelectedRef = React.useRef(false);

  const onSelect = React.useCallback(() => {
    if (wasSelectedRef.current) {
      return false;
    }
    const pos = getPos();
    if (typeof pos === 'number') {
      editor.view.dispatch(
        editor.state.tr.setSelection(NodeSelection.create(editor.state.doc, pos))
      );
    }
    return true;
  }, [editor, getPos]);

  return (
    <div
      onMouseDownCapture={() => {
        wasSelectedRef.current = selected;
      }}
    >
      <TocView
        tocId={String(node.attrs.id || '')}
        data={data as unknown as TocData}
        headings={headings}
        mode="editor"
        onSelect={onSelect}
        onNavigate={heading => {
          const target = editor.view.dom.querySelector(
            `[data-ricos-id="${heading.nodeId}"]`
          ) as HTMLElement | null;

          target?.scrollIntoView({ behavior: getScrollBehavior(), block: 'start' });
        }}
      />
    </div>
  );
};
