import type { PluginToolbarConfig } from './../ricos-types/index.js';
import { createAnimationButton } from './../_shared/plugin-toolbar/create-animation-button.js';
import { createDeleteButton } from './../_shared/plugin-toolbar/create-delete-button.js';
import { createSettingsButton } from './../_shared/plugin-toolbar/create-settings-button.js';
import { createSeparator } from './../_shared/plugin-toolbar/separator/create-separator.js';
import { FLOATING_PLUGIN_TOOLBAR } from './../toolbars-v3/index.js';

import { TOC_SETTINGS_BUTTON, TOC_SETTINGS_MODAL } from './data-hooks.js';
import { TocSettingsModal } from './modals/settings-modal.js';

export const getToolbarButtons: PluginToolbarConfig['getButtons'] = (_config, services) => {
  const settingsButton = createSettingsButton({
    modalId: TOC_SETTINGS_MODAL,
    showLabel: true,
    dataHook: TOC_SETTINGS_BUTTON,
    command: ({ referenceElement, attributes: { selectedNode } }) => {
      services.modals.togglePluginPanel({
        id: TOC_SETTINGS_MODAL,
        Component: TocSettingsModal,
        componentProps: {
          nodeId: selectedNode.attrs.id,
        },
        isMobile: services.context.isMobile,
        positioning: {
          referenceElement:
            referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
            referenceElement,
          placement: 'right-start',
        },
        onClickOutside: {
          on: 'pointerup',
          handler: () => {},
        },
        focusReturnElement: referenceElement,
      });
    },
  });

  const separator = createSeparator();
  const animation = createAnimationButton(services);
  const deleteButton = createDeleteButton();

  return services.context.environment === 'wixel'
    ? [settingsButton, animation, deleteButton]
    : [settingsButton, animation, separator, deleteButton];
};
