import { List, ListSmall } from '@wix/wix-ui-icons-common/lazy';

import type { TocData } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { EditorPluginCreator } from './../ricos-types/index.js';
import { quickActionsModalSections, RicosPluginToolbarNames } from './../ricos-types/index.js';

import { TOC_DEFAULTS } from './defaults.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import { tocConverter } from './toc-converter.js';
import type { TocPluginEditorConfig } from './types.js';
import { TOC_TYPE } from './types.js';

export const pluginToc: EditorPluginCreator<TocPluginEditorConfig> = (
  config = {} as TocPluginEditorConfig
) => {
  return {
    config: { ...config, type: 'toc' as const },
    type: TOC_TYPE,
    pmMarkConverters: [],
    pmNodeConverters: [tocConverter],
    tiptapExtensions,
    getAddButtons,
    toolbar: {
      names: [RicosPluginToolbarNames.TOC],
      getButtons: getToolbarButtons,
    },
    getQuickActions: ({ pluginServices }) => [
      {
        id: TOC_TYPE,
        title: 'TocPlugin_InsertButton',
        icon: pluginServices?.context.isMobile ? ListSmall : List,
        section: quickActionsModalSections.FormatLayout,
        tags: ['table of contents', 'toc', 'outline', 'headings', 'navigation'],
        command: ({ publicCommands }) => {
          publicCommands.insertBlockWithBlankLines(TOC_TYPE, TOC_DEFAULTS as TocData);
        },
      },
    ],
  };
};
