import React, { useContext } from 'react';

import { NodeTreeMapContext } from './../../ricos-context/viewer/node-tree-map-context.js';
import type { Node as RicosNode, TocData } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { TOC_DEFAULTS } from '../defaults.js';
import { extractHeadingsFromRicosNodes } from '../heading-extraction.js';
import { getScrollBehavior, TocView } from '../toc-view.js';

export const TocRenderer = ({ node, nodeIndex, NodeViewContainer }: NodeViewRendererProps) => {
  const { nodeTreeMap } = useContext(NodeTreeMapContext);
  const data = {
    ...TOC_DEFAULTS,
    ...node.tocData,
  } as TocData;
  const headings = extractHeadingsFromRicosNodes(
    Object.values(nodeTreeMap)
      .filter(entry => !entry.parent)
      .map(entry => entry.node as RicosNode),
    data.includedHeadings ?? TOC_DEFAULTS.includedHeadings
  );

  return (
    <NodeViewContainer node={node} nodeIndex={nodeIndex}>
      <TocView
        tocId={String(node.id || '')}
        data={data}
        headings={headings}
        mode="viewer"
        onNavigate={heading => {
          if (typeof document === 'undefined') {
            return;
          }
          const targetAnchor = document.getElementById(heading.anchor);
          const targetHeading =
            (targetAnchor?.closest?.('h1, h2, h3, h4, h5, h6') as HTMLElement | null) ??
            targetAnchor;
          targetHeading?.scrollIntoView?.({
            behavior: getScrollBehavior(),
            block: 'start',
          });
          targetHeading?.focus?.({ preventScroll: true });
          window.history?.pushState?.(null, '', `#${heading.anchor}`);
        }}
      />
    </NodeViewContainer>
  );
};
